PROJECTS = [
    ("demo_bot", {"stage": "prototype"}),
    ("support_rag", {"stage": "production"}),
    ("batch_pipeline", {"stage": "production"}),
]

def choose_endpoint(project):
    if project["stage"] == "production":
        return "vertex_ai"
    return "ai_studio"

vertex_count = 0
for name, project in PROJECTS:
    endpoint = choose_endpoint(project)
    if endpoint == "vertex_ai":
        vertex_count += 1
    print(f"{name}: {endpoint}")

print(f"production_ratio={vertex_count}/{len(PROJECTS)}")
